changeSet.sql:
INSERT INTO stretchy_report ( report_name, report_type, report_subtype, report_category, report_sql, description, core_report, use_report, self_service_user_report ) VALUES ( 'Movimientos de Partidas', 'Table', 'VisualPartidaMoves', 'Accounting', $report$ WITH selected_offices AS ( SELECT child.id FROM m_office selected JOIN m_office child ON child.hierarchy LIKE selected.hierarchy || '%' WHERE selected.id = CAST('${officeId}' AS BIGINT) AND child.hierarchy LIKE '${currentUserHierarchy}' || '%' ), posting_groups AS ( SELECT COALESCE('V:' || entry.voucher_id::text, 'T:' || entry.transaction_id) AS posting_key, MIN(entry.entry_date) AS entry_date, MIN(entry.office_id) AS report_office_id, CASE WHEN COUNT(entry.ref_num) = COUNT(*) AND COUNT(DISTINCT entry.ref_num) = 1 THEN MIN(entry.ref_num) ELSE 'TX-' || MIN(entry.transaction_id) END AS entry_number, COALESCE(NULLIF(BTRIM(MAX(voucher.header_concept)), ''), CASE WHEN COUNT(DISTINCT NULLIF(BTRIM(entry.header_concept), '')) = 1 THEN MIN(NULLIF(BTRIM(entry.header_concept), '')) END, '-') AS entry_concept, CASE WHEN COUNT(*) = COUNT(NULLIF(BTRIM(entry.description), '')) AND COUNT(DISTINCT NULLIF(BTRIM(entry.description), '')) = 1 THEN MIN(BTRIM(entry.description)) ELSE '' END AS entry_description, CASE WHEN ROUND(SUM(CASE WHEN entry.type_enum = 2 THEN entry.amount WHEN entry.type_enum = 1 THEN -entry.amount ELSE 0 END), 2) <> 0 THEN 'DESCUADRADA' WHEN COUNT(*) < 2 OR BOOL_OR(entry.amount = 0) THEN 'INCOMPLETA' WHEN BOOL_OR(COALESCE(entry.reversed, FALSE)) THEN 'REVERTIDA' ELSE 'CONTABILIZADA' END AS entry_status, BOOL_AND(line_office.hierarchy LIKE '${currentUserHierarchy}' || '%') AS all_lines_permitted FROM acc_gl_journal_entry entry JOIN m_office line_office ON line_office.id = entry.office_id LEFT JOIN credesal_gl_voucher voucher ON voucher.id = entry.voucher_id WHERE entry.currency_code = 'USD' AND entry.transaction_id IS NOT NULL AND entry.type_enum IN (1, 2) GROUP BY COALESCE('V:' || entry.voucher_id::text, 'T:' || entry.transaction_id) ), selected_groups AS ( SELECT posting_groups.*, office.external_id AS report_branch_code, CASE office.external_id WHEN '1' THEN 'AGENCIA CENTRAL' WHEN '2' THEN 'USULUTAN' ELSE UPPER(office.name) END AS report_branch FROM posting_groups JOIN selected_offices selected ON selected.id = posting_groups.report_office_id JOIN m_office office ON office.id = posting_groups.report_office_id WHERE posting_groups.entry_date BETWEEN CAST('${startDate}' AS DATE) AND CAST('${endDate}' AS DATE) AND posting_groups.all_lines_permitted AND (NULLIF(BTRIM('${partidaNumber}'), '') IS NULL OR posting_groups.entry_number = BTRIM('${partidaNumber}')) ), detail AS ( SELECT selected_groups.posting_key, selected_groups.entry_number, selected_groups.entry_date, selected_groups.report_branch_code, selected_groups.report_office_id, selected_groups.report_branch, selected_groups.entry_concept, selected_groups.entry_description, selected_groups.entry_status, ROW_NUMBER() OVER (PARTITION BY selected_groups.posting_key ORDER BY entry.id) AS line_sequence, account.gl_code AS account_code, account.name AS account_name, CASE line_office.external_id WHEN '1' THEN 'AGENCIA CENTRAL' WHEN '2' THEN 'USULUTAN' ELSE UPPER(line_office.name) END AS line_branch, ROUND(CASE WHEN entry.type_enum = 2 THEN entry.amount ELSE 0 END, 2) AS debit, ROUND(CASE WHEN entry.type_enum = 1 THEN entry.amount ELSE 0 END, 2) AS credit FROM selected_groups JOIN acc_gl_journal_entry entry ON COALESCE('V:' || entry.voucher_id::text, 'T:' || entry.transaction_id) = selected_groups.posting_key JOIN acc_gl_account account ON account.id = entry.account_id JOIN m_office line_office ON line_office.id = entry.office_id WHERE entry.currency_code = 'USD' AND entry.type_enum IN (1, 2) ), balanced AS ( SELECT detail.*, SUM(debit - credit) OVER (PARTITION BY posting_key ORDER BY line_sequence ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_balance, SUM(debit) OVER (PARTITION BY posting_key) AS entry_debit_total, SUM(credit) OVER (PARTITION BY posting_key) AS entry_credit_total, COUNT(*) OVER (PARTITION BY posting_key) AS entry_line_count FROM detail ) SELECT ROW_NUMBER() OVER (ORDER BY DATE_TRUNC('month', entry_date), report_office_id, entry_date, entry_number, posting_key, line_sequence) AS "Orden", report_office_id AS "Id Oficina", report_branch_code AS "Código Sucursal", report_branch AS "Sucursal", entry_number AS "Partida", entry_date AS "Fecha", entry_concept AS "Concepto Partida", entry_description AS "Descripción Partida", entry_status AS "Estado", line_sequence AS "Orden Línea", account_code AS "No. Cuenta", account_name AS "Concepto", line_branch AS "Sucursal Línea", debit AS "Cargos", credit AS "Abonos", running_balance AS "Saldo", entry_debit_total AS "Total Cargos", entry_credit_total AS "Total Abonos", entry_debit_total - entry_credit_total AS "Saldo Partida", entry_line_count AS "Líneas Partida" FROM balanced ORDER BY "Orden" $report$, 'Partidas contables nativas con líneas y saldo progresivo de Fineract.', FALSE, TRUE, FALSE ) ON CONFLICT (report_name) DO UPDATE SET report_type = EXCLUDED.report_type, report_subtype = EXCLUDED.report_subtype, report_category = EXCLUDED.report_category, report_sql = EXCLUDED.report_sql, description = EXCLUDED.description, core_report = EXCLUDED.core_report, use_report = EXCLUDED.use_report, self_service_user_report = EXCLUDED.self_service_user_report;
DELETE FROM stretchy_report_parameter WHERE report_id = (SELECT id FROM stretchy_report WHERE report_name = 'Movimientos de Partidas');
INSERT INTO stretchy_report_parameter (report_id, parameter_id, report_parameter_name) SELECT report.id, parameter.id, parameter.parameter_variable FROM stretchy_report report JOIN stretchy_parameter parameter ON parameter.parameter_name IN ( 'OfficeIdSelectOne', 'startDateSelect', 'endDateSelect', 'partidaNumberOptional' ) WHERE report.report_name = 'Movimientos de Partidas';
DO $validation$ BEGIN IF ( SELECT COUNT(*) FROM stretchy_report_parameter usage JOIN stretchy_report report ON report.id = usage.report_id WHERE report.report_name = 'Movimientos de Partidas' AND usage.report_parameter_name IN ('officeId', 'startDate', 'endDate', 'partidaNumber') ) <> 4 THEN RAISE EXCEPTION 'Movimientos de Partidas requires officeId, startDate, endDate, partidaNumber parameters'; END IF; END $validation$;
INSERT INTO m_permission (grouping, code, entity_name, action_name, can_maker_checker) SELECT 'report', 'READ_Movimientos de Partidas', 'Movimientos de Partidas', 'READ', FALSE WHERE NOT EXISTS (SELECT 1 FROM m_permission WHERE code = 'READ_Movimientos de Partidas');
